import { describe, expect, it } from "vitest";

import defaultMessages from "../../../locale/defaultMessages.json";
import mn from "../../../locale/mn.json";
import type { LocaleMessages } from "./Locale";

// Translation coverage (PLAN M11 decision 6): every dashboard message has a Mongolian text, and
// mn.json has nothing for a message that no longer exists. defaultMessages.json is regenerated by
// `pnpm extract-messages` (CI checks it is up to date), so a new message fails here until it is
// translated in locale/mn.json.
const english = defaultMessages as LocaleMessages;
const mongolian = mn as LocaleMessages;

describe("Mongolian translations", () => {
  it("cover every message", () => {
    const missing = Object.keys(english).filter((id) => !mongolian[id]?.string.trim());

    expect(missing.map((id) => `${id}: ${english[id]?.string}`)).toEqual([]);
  });

  it("have no entry for an unknown message", () => {
    const unknown = Object.keys(mongolian).filter((id) => !(id in english));

    expect(unknown).toEqual([]);
  });
});
